// Package sources turns each coding agent's session logs into the IR (package ir).
//
// One Adapter per agent: omp (reference implementation, verified against omp 18.13.2 and covered
// by fixtures generated by omp itself), Claude Code and Codex (skeletons, see their files). The
// registry below is the only place that knows the list; the CLI and tests go through it.
package sources

import (
	"bytes"
	"errors"
	"io"
	"os"
	"runtime"
	"sort"
	"strings"
	"sync"

	"github.com/veritas501/mem-grep/internal/config"
	"github.com/veritas501/mem-grep/internal/ir"
)

// Adapter reads one agent's sessions.
type Adapter interface {
	Kind() ir.SourceKind
	// Discover finds this agent's session files under the configured roots.
	Discover(cfg *config.Config) []ir.SourceFile
	// Sniff reports whether a file given explicitly (a path passed to `mg show`, or --path) is this
	// agent's format; head is the file's first few KB.
	Sniff(path string, head []byte) bool
	// Open parses a file. It returns (nil, nil) when the file is not a session after all (e.g. no
	// header) and an error when it cannot be read.
	Open(f ir.SourceFile) (*ir.Session, error)
}

// ScanOptions let a search read sessions faster. Other callers never set them.
type ScanOptions struct {
	// Keep, when set, is asked about records that cannot open a turn (assistant messages, tool
	// results), with the roles of the lines the record may render. A record it rejects is decoded
	// only as far as the transcript's structure needs: it comes back as one line with Elided set
	// and no text. A search passes a filter that rejects records whose raw bytes cannot contain a
	// match, or whose roles it does not search.
	Keep func(record []byte, roles []ir.Role) bool
	// Raw asks for unredacted text. The caller must redact before matching for real or showing
	// anything. Adapters may ignore it and redact anyway.
	Raw bool
}

// BytesOpener is an Adapter that parses bytes the caller already read (decompressed).
type BytesOpener interface {
	OpenBytes(f ir.SourceFile, raw []byte, opt ScanOptions) (*ir.Session, error)
}

// OpenBytes parses f from raw, the bytes ReadRaw returned, without reading the file again.
func OpenBytes(f ir.SourceFile, raw []byte, opt ScanOptions) (*ir.Session, error) {
	a := Get(f.Kind)
	if a == nil {
		return nil, ErrUnknownFormat
	}
	if b, ok := a.(BytesOpener); ok {
		return b.OpenBytes(f, raw, opt)
	}
	return a.Open(f)
}

// Synthetic is the text renderers write themselves rather than copy from a record: notation,
// notes, defaults, truncation and redaction markers. Each entry is a complete run between two
// pieces of record content; "\x00" marks the start or end of a line, where no content can touch
// it. A search term that overlaps a run may match a line whose source record does not contain
// the term, so it must not be used to skip records or files unread. Keep it in sync with the
// renderers (omp.go, claude.go, codex.go, util.Truncate*, util.Redact).
var Synthetic = []string{
	// lines
	"\x00USER: ", "\x00ASSISTANT: ", "\x00USER (answering the agent): ", "\x00TASK for subagent: ",
	"\x00TASK for subagent \"", "\": ", "\x00USER SHELL $ ", "\x00USER PYTHON >>> ", " (exit ", ")\n",
	" (exit cancelled)\n", " (exit ?)\n",
	// tool calls: "  → name(k=v k=v (+rest,keys))"
	"\x00  → ", "(", ")\x00", "=", " ", " (+", ",", ")", ")\x00", "\x00  → shell(command=", "\x00  → web_search(",
	// tool results
	"\x00  ✗ ", " failed: ", "\x00  ✗ tool failed: ", "\x00  ✓ ", ": ", "\x00  ✓ tool: ", "\x00  ✓ tool\x00",
	// notes
	"\x00  [assistant turn aborted by the user]\x00", "\x00  [assistant error: ", "]\x00", "\x00  [assistant error: unknown]\x00",
	"\x00[context reset: a new root was started; earlier conversation is no longer in context]\x00",
	"\x00[branch: rewound to earlier point #", "; everything after that point on the previous path was abandoned]\x00",
	"\x00[branch: the user rolled back earlier turns; what came after them was abandoned]\x00",
	"\x00[summary of the abandoned branch: ", "\x00[user ran /clear — a new topic likely starts here]\x00",
	"\x00[user ran ", "\x00  [command output: ",
	"\x00[mode: ", "\x00[message from another agent: ", "[image]", "\n[file: ", "\n",
	// util.Truncate / Tail / TruncateMiddle (the omitted count is digits: see grep.skippable)
	"…\x00", "\x00…", "\n…[", " chars omitted]…\n",
	// util.Redact
	"[REDACTED]", " [REDACTED]", "[REDACTED PRIVATE KEY]", "[REDACTED JWT]",
}

// SyntheticImplies lists, for some runs of Synthetic, words the raw record always contains when
// the run is rendered (the role or reason that triggers it): a term inside one of those words
// may overlap the run and still be used to skip records. Verified for omp, Claude Code and Codex.
var SyntheticImplies = map[string][]string{
	"\x00USER: ":      {"user"},
	"\x00ASSISTANT: ": {"assistant"},
	"\x00  [assistant turn aborted by the user]\x00": {"aborted"},
	"\x00  [assistant error: ":                       {"error"},
	"\x00  [assistant error: unknown]\x00":           {"error"},
}

// All is every known adapter, in sniffing order.
var All = []Adapter{OMP{}, Codex{}, Qwen{}, Gemini{}, Claude{}, OpenCode{}}

// Kinds lists every known agent, in registry order.
func Kinds() []ir.SourceKind {
	out := make([]ir.SourceKind, len(All))
	for i, a := range All {
		out[i] = a.Kind()
	}
	return out
}

// Get returns the adapter for kind.
func Get(kind ir.SourceKind) Adapter {
	for _, a := range All {
		if a.Kind() == kind {
			return a
		}
	}
	return nil
}

// Discover lists the session files of every agent: parents before children, older before newer.
func Discover(cfg *config.Config) []ir.SourceFile {
	var out []ir.SourceFile
	for _, a := range All {
		out = append(out, a.Discover(cfg)...)
	}
	sort.SliceStable(out, func(i, j int) bool {
		ci, cj := out[i].ParentKey != "", out[j].ParentKey != ""
		if ci != cj {
			return !ci
		}
		return out[i].MtimeMs < out[j].MtimeMs
	})
	return out
}

// ErrUnknownFormat is returned by FileFor for files no adapter recognises.
var ErrUnknownFormat = errors.New("not a session file of a supported agent")

// FileFor describes a file given explicitly by path, detecting its format. It works for any
// supported agent.
func FileFor(path string) (ir.SourceFile, error) {
	st, err := os.Stat(path)
	if err != nil {
		return ir.SourceFile{}, err
	}
	head, err := readHead(path, 16384)
	if err != nil {
		return ir.SourceFile{}, err
	}
	for _, a := range All {
		if a.Sniff(path, head) {
			f := ir.SourceFile{Kind: a.Kind(), Path: path, Key: path, Size: st.Size(), MtimeMs: float64(st.ModTime().UnixNano()) / 1e6}
			if a.Kind() == ir.Codex {
				f.Key = codexKey(path)
			}
			return f, nil
		}
	}
	return ir.SourceFile{}, ErrUnknownFormat
}

// Open parses f with its adapter.
func Open(f ir.SourceFile) (*ir.Session, error) {
	a := Get(f.Kind)
	if a == nil {
		return nil, ErrUnknownFormat
	}
	return a.Open(f)
}

func readHead(path string, n int) ([]byte, error) {
	fh, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer fh.Close()
	buf := make([]byte, n)
	k, _ := fh.Read(buf)
	buf = buf[:k]
	if isZstd(buf) {
		// Compressed Codex rollout: sniff the decompressed start.
		data, err := readMaybeCompressed(path)
		if err != nil {
			return nil, err
		}
		if len(data) > n {
			data = data[:n]
		}
		return data, nil
	}
	return buf, nil
}

func firstLine(head []byte) []byte {
	if i := bytes.IndexByte(head, '\n'); i >= 0 {
		return head[:i]
	}
	return head
}

// ReadRaw returns a session file's bytes, decompressing .jsonl.zst rollouts. Search tools use it
// to skip files that cannot match before paying for a full parse (see OpenBytes).
func ReadRaw(path string) ([]byte, error) { return readMaybeCompressed(path) }

// Container is an Adapter whose sessions live inside a database file: SessionsIn lists them (ok is
// false when the file is not such a database). FilesUnder uses it for databases given explicitly.
type Container interface {
	SessionsIn(path string) (files []ir.SourceFile, ok bool)
}

// RawReader is an Adapter whose sessions are not plain files (a row set in a database): it builds
// the bytes OpenBytes parses, so a search can prefilter them like a file's.
type RawReader interface {
	ReadRaw(f ir.SourceFile) ([]byte, error)
}

// ReadFileInto returns a session's raw bytes (see ReadRawInto), asking the adapter for sessions that
// live inside a shared container.
func ReadFileInto(f ir.SourceFile, buf []byte) ([]byte, error) {
	if f.Inner != "" {
		if a, ok := Get(f.Kind).(RawReader); ok {
			return a.ReadRaw(f)
		}
		return nil, ErrUnknownFormat
	}
	return ReadRawInto(f.Path, buf)
}

// ReadRawInto is ReadRaw reusing buf's storage when it is large enough.
func ReadRawInto(path string, buf []byte) ([]byte, error) {
	fh, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer fh.Close()
	st, err := fh.Stat()
	if err != nil {
		return nil, err
	}
	if n := int(st.Size()) + 512; cap(buf) < n {
		buf = make([]byte, 0, n)
	}
	buf = buf[:0]
	for {
		if len(buf) == cap(buf) {
			buf = append(buf, 0)[:len(buf)]
		}
		n, err := fh.Read(buf[len(buf):cap(buf)])
		buf = buf[:len(buf)+n]
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if isZstd(buf) {
		return decompress(buf)
	}
	return buf, nil
}

// FilesUnder describes every session file of a supported agent at path: the file itself, or
// every *.jsonl / *.jsonl.zst below a directory whose format an adapter recognises. Subagent
// links are not resolved (use Discover for that).
func FilesUnder(path string) ([]ir.SourceFile, error) {
	st, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if !st.IsDir() && isSQLite(path) {
		for _, a := range All {
			if c, ok := a.(Container); ok {
				if files, ok := c.SessionsIn(path); ok {
					return files, nil
				}
			}
		}
		return nil, ErrUnknownFormat
	}
	if !st.IsDir() {
		f, err := FileFor(path)
		if err != nil {
			return nil, err
		}
		return []ir.SourceFile{f}, nil
	}
	var out []ir.SourceFile
	found := walkFiles(path, func(n string) bool {
		return strings.HasSuffix(n, ".jsonl") || strings.HasSuffix(n, ".jsonl.zst") || strings.HasSuffix(n, ".db")
	}, 8)
	// Sniffing reads the head of every file: do it in parallel, keep the walk's order.
	files := make([]ir.SourceFile, len(found))
	ok := make([]bool, len(found))
	var wg sync.WaitGroup
	next := make(chan int)
	for w := 0; w < runtime.GOMAXPROCS(0); w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range next {
				if strings.HasSuffix(found[i].path, ".db") {
					continue // databases are listed below
				}
				f, err := FileFor(found[i].path)
				files[i], ok[i] = f, err == nil
			}
		}()
	}
	for i := range found {
		next <- i
	}
	close(next)
	wg.Wait()
	for i, f := range files {
		switch {
		case ok[i]:
			out = append(out, f)
		case strings.HasSuffix(found[i].path, ".db") && isSQLite(found[i].path):
			if sub, err := FilesUnder(found[i].path); err == nil {
				out = append(out, sub...)
			}
		}
	}
	return out, nil
}
